import json, os, glob

# Look for settings.json files
for p in glob.glob('/tmp/**/settings.json', recursive=True):
    print(p)
    try:
        with open(p) as f:
            data = json.load(f)
            if 'mcpServers' in data or 'nethack' in str(data):
                print(json.dumps(data, indent=2)[:2000])
    except:
        pass
